<?php
namespace App\Livewire\Admin\Analytics;use App\Models\User;use App\Services\AdminAnalyticsService;use Livewire\Attributes\Url;use Livewire\Component;
class Index extends Component{#[Url]public string $from='';#[Url]public string $to='';#[Url]public ?int $sales_user=null;public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->isAccount()||auth()->user()->isManager(),403);$this->from=$this->from?:now()->subDays(30)->toDateString();$this->to=$this->to?:today()->toDateString();if(auth()->user()->isSales()&&!auth()->user()->isAdmin())$this->sales_user=auth()->id();}public function render(AdminAnalyticsService $service){return view('livewire.admin.analytics.index',['summary'=>$service->summary($this->from,$this->to,$this->sales_user),'pipeline'=>$service->pipeline($this->from,$this->to,$this->sales_user),'salesUsers'=>User::where('role','sales')->orderBy('name')->get()])->layout('components.layouts.admin',['title'=>'Analytics']);}}
